const BALL = "ph10_ball"
const FALL = vec(0, -0.04, 0)

game `ph10 %entity_uuid%`
game ph10_hits

when entity_spawn {
    wait(1)
    if not entity.name_equals(BALL) {
        return
    }
    `ph10 %entity_uuid%` = vec(0, 0, 0)
    ph10_hits = 0
    while entity.exists() {
        wait(1)
        v = `ph10 %entity_uuid%` + FALL
        speed = get_vector_length(v)
        hit = ray_trace_result(variable_for_hit_block_face: face, start: set_location_direction(value.location, v), max_distance: speed + 0.05, ray_size: 0, ray_collision_mode: only_blocks)
        if var.is_type(hit, location) {
            if ph10_hits == 0 {
                @all send_message("ph10 удар грань=${face}")
            }
            ph10_hits += 1
            v = reflect_vector_product(v, get_vector_from_block_face(face), 0.7)
        }
        entity.teleport(shift_location_on_vector(value.location, v))
        `ph10 %entity_uuid%` = v
    }
}

