when projectile_hit {
    if not entity.name_equals(BALL) {
        end_thread()
    }
    get_vector_all_components(value.velocity, vx, vy, vz)
    get_vector_all_components(value.direction_of_view, dx, dy, dz)
    down = "нет"
    if vy < 0 {
        down = "да"
    }
    up = "нет"
    if dy > 0 {
        up = "да"
    }
    @all send_message("ph12 грань=${value.event_block_face} падал=${down} взгляд вверх=${up}")
    normal = get_vector_from_block_face(value.event_block_face)
    bounce = reflect_vector_product(value.velocity, normal, 0.6)
    game.launch_projectile(item(snowball), shift_location_on_vector(value.location, normal, 0.3), 0.5, 0, SECOND)
    @last set_location(bounce, increment: false)
    entity.remove()
}

when projectile_hit {
    if not entity.name_equals(SECOND) {
        end_thread()
    }
    @all send_message("ph12 второй отскок")
    entity.remove()
}

