process ph13_drive(id: text) {
    speed = 0
    wait(2)
    while player.is_riding_entity(id, compare_mode: name_or_uuid) {
        wait(1)
        gas = value.steer_forward
        if gas == 0 {
            speed = speed * 0.95
        } else {
            `ph13 газ %player%` = gas
            speed = clamp(speed + gas * 0.02, -0.2, 0.8)
        }
        entity_by_name(id)
        @current entity.launch_forward(speed, increment: false, launch_axis: yaw)
        reset()
    }
    entity_by_name(id)
    @current entity.remove()
    wait(2)
    entity_by_name(id)
    @default send_message("ph13 убрана размер=${value.selection_size}")
}

